(() => {
'use strict';
const state=window.celestialTravel={phase:'idle',kind:null,returnMode:'telescope'},screen=document.querySelector('#celestial-destination'),flight=document.querySelector('#celestial-flight'),info=document.querySelector('#destination-content');let originFocus;
const data={blackhole:{number:'01',name:'Black hole',section:'about',tag:'THE PERSON',heading:'Hi, I’m<br><em>Rushik.</em>',body:'<p class="destination-lead">First-year B.Tech student.<br>Still studying. Still learning.</p><p>This is my first portfolio — a small window into where I am, and the journey ahead.</p>',motion:'Orbiting accretion flow',source:'https://science.nasa.gov/universe/black-holes/anatomy/'},pulsar:{number:'02',name:'Pulsar',section:'learning',tag:'THE JOURNEY',heading:'Not there yet.<br><em>On my way.</em>',body:'<p class="destination-lead">First-year B.Tech.<br>A new chapter of learning.</p><p>I’m still studying and figuring things out. This space begins here, with room for what comes next.</p><div class="destination-status"><span class="live-dot"></span> LEARNING IN PROGRESS</div><button type="button" class="learning-stars-scroll pulsar-scroll-cue" data-learning-scroll aria-label="Scroll down to explore my learning stars"><span class="pulsar-scroll-icon" aria-hidden="true"><i></i></span><span>Scroll to explore</span></button>',motion:'Rotating magnetic beams',source:'https://science.nasa.gov/mission/hubble/science/science-behind-the-discoveries/hubble-pulsars/'},comet:{number:'03',name:'Comet',section:'education',tag:'THE FOUNDATION',heading:'Small steps.<br><em>Solid ground.</em>',body:'<p>The milestones that brought me here.</p><div class="destination-results"><div><span>CBSE · CLASS 10</span><strong>89.2<small>%</small></strong></div><div><span>CBSE · CLASS 12</span><strong>86.4<small>%</small></strong></div></div><div class="destination-status">B.Tech · First year · Still studying</div>',motion:'Drifting dust and an anti-solar tail',source:'https://science.nasa.gov/solar-system/comets/facts/'},astronaut:{number:'04',name:'Astronaut',section:'contact',tag:'THE CONNECTION',heading:'Let’s <em>connect.</em>',body:'<p class="destination-lead">A signal across the cosmos.</p><p id="radio-status" role="status" aria-live="polite">Tap the astronaut’s radio to find a signal.</p><button type="button" class="radio-connect" id="radio-connect" aria-controls="radio-contacts" aria-expanded="false">Connect radio</button><div id="radio-contacts" hidden><a class="destination-link" href="mailto:vvrrushikchundru@gmail.com"><span>EMAIL</span>vvrrushikchundru@gmail.com ↗</a><a class="destination-link" href="https://github.com/Rushik-Code" target="_blank" rel="noopener noreferrer"><span>GITHUB</span>Rushik-Code ↗</a><a class="destination-link" href="https://www.linkedin.com/in/rushik-chundru-138814434/" target="_blank" rel="noopener noreferrer"><span>LINKEDIN</span>Rushik Chundru ↗</a></div>',motion:'Searching for a signal',source:''}};
function select(kind){if(state.phase!=='idle'||document.body.classList.contains('is-intro'))return;originFocus=document.activeElement;state.kind=kind;state.sequence=(state.sequence||0)+1;state.phase='queued';state.label=data[kind].name;document.querySelector('#cosmic-contact').close();document.body.classList.add('is-travel');flight.hidden=false;screen.hidden=true;flight.querySelector('button').focus({preventScroll:true});document.querySelector('#scope-return').hidden=false;document.querySelector('#flight-object').textContent=data[kind].name;}
window.selectCelestialDestination=select;
document.addEventListener('click',event=>{const object=event.target.closest('.star-link,[data-sky-object]');if(!object)return;const kind=object.dataset.skyObject||object.querySelector('[data-object]')?.dataset.object;if(!data[kind])return;event.preventDefault();event.stopImmediatePropagation();select(kind)},true);

function typeDestinationText(target=info){
 info.dataset.typingMode=document.body.classList.contains('reduced')?'instant':'animated';
 if(info.dataset.typingMode==='instant')return;
 const walker=document.createTreeWalker(target,NodeFilter.SHOW_TEXT),nodes=[];let node;
 while((node=walker.nextNode()))if(node.textContent.trim()&&!node.parentElement.closest('[hidden],[data-learning-cluster]'))nodes.push(node);
 const total=nodes.reduce((sum,n)=>sum+Array.from(n.textContent).length,0),interval=Math.min(5,1150/Math.max(total,1));let cursor=0;
 for(const text of nodes){const fragment=document.createDocumentFragment(),spoken=document.createElement('span');spoken.className='destination-spoken';spoken.textContent=text.textContent;fragment.append(spoken);
 // Keep whole words together while reserving their full layout from the first frame.
 for(const word of text.textContent.split(/(\s+)/)){if(!word)continue;const group=document.createElement('span');group.className=/^\s+$/.test(word)?'destination-type-space':'destination-type-word';group.setAttribute('aria-hidden','true');for(const character of Array.from(word)){const glyph=document.createElement('span');glyph.className='destination-type-glyph';glyph.textContent=character;glyph.style.setProperty('--type-delay',(90+cursor++*interval).toFixed(1)+'ms');group.append(glyph)}fragment.append(group)}text.replaceWith(fragment)}
 info.classList.add('destination-typing');
 const spokenNodes=[...target.querySelectorAll('.destination-spoken')];setTimeout(()=>{for(const spoken of spokenNodes){if(!spoken.isConnected)continue;let next=spoken.nextSibling;while(next?.nodeType===1&&(next.classList.contains('destination-type-word')||next.classList.contains('destination-type-space'))){const following=next.nextSibling;next.remove();next=following}spoken.replaceWith(document.createTextNode(spoken.textContent))}},1450);
}

document.addEventListener('celestial:arrived',()=>{const d=data[state.kind];info.classList.remove('destination-typing');info.innerHTML='<span class="destination-index">MISSION PROFILE / '+d.number+'</span><span class="eyebrow">'+d.tag+'</span><h2 id="destination-heading" tabindex="-1">'+d.heading+'</h2>'+d.body+(state.kind==='pulsar'?(window.learningClusterMarkup?.('destination-learning-'+state.sequence)||''):'');window.mountLearningClusters?.(info);typeDestinationText();flight.hidden=true;screen.hidden=false;document.body.classList.remove('is-travel');document.body.classList.add('is-destination');info.querySelector('h2').focus({preventScroll:true});});

const radioHotspot=document.querySelector('#radio-hotspot');let radioTimer;
function connectRadio(){if(state.kind!=='astronaut'||state.phase!=='arrived')return;clearTimeout(radioTimer);const contacts=info.querySelector('#radio-contacts'),button=info.querySelector('#radio-connect'),status=info.querySelector('#radio-status');if(!contacts)return;const sequence=state.sequence;status.textContent='Searching the cosmos…';button.disabled=true;radioHotspot.classList.add('is-transmitting');radioHotspot.querySelector('span').textContent='Searching…';document.dispatchEvent(new Event('radio:pulse'));
radioTimer=setTimeout(()=>{if(state.sequence!==sequence||state.phase!=='arrived')return;status.textContent='Signal found. Let’s connect.';const first=contacts.hidden;contacts.hidden=false;if(first)typeDestinationText(contacts);button.disabled=false;button.textContent='Send another signal';button.setAttribute('aria-expanded','true');radioHotspot.setAttribute('aria-expanded','true');radioHotspot.classList.remove('is-transmitting');radioHotspot.querySelector('span').textContent='Signal found';},document.body.classList.contains('reduced')?0:650)}
radioHotspot.addEventListener('click',connectRadio);info.addEventListener('click',e=>{if(e.target.closest('#radio-connect'))connectRadio()});document.addEventListener('radio:activate',connectRadio);
document.addEventListener('celestial:arrived',()=>{clearTimeout(radioTimer);radioHotspot.hidden=state.kind!=='astronaut';radioHotspot.classList.remove('is-transmitting');radioHotspot.setAttribute('aria-expanded','false');radioHotspot.querySelector('span').textContent='Click this to contact'});
document.addEventListener('celestial:returned',()=>{clearTimeout(radioTimer);radioHotspot.hidden=true});

function leave(mode){if(state.phase==='idle'||state.phase==='returning')return;clearTimeout(radioTimer);radioHotspot.hidden=true;state.returnMode=mode;state.phase='returning';screen.classList.add('destination-out');flight.hidden=true;if(mode==='telescope')window.openTelescopeView?.();else window.exitTelescopeView?.();}
document.querySelector('#destination-telescope').onclick=()=>leave('telescope');document.querySelector('#destination-map').onclick=()=>leave('map');document.querySelector('#flight-cancel').onclick=()=>leave('map');
document.addEventListener('celestial:returned',()=>{screen.hidden=true;screen.classList.remove('destination-out');document.body.classList.remove('is-travel','is-destination');if(state.returnMode==='map'){requestAnimationFrame(()=>document.querySelector('.quick-nav a[href="#constellation"]').click())}else document.querySelector('#scope-drag').focus({preventScroll:true})});
document.addEventListener('keydown',event=>{if(state.phase==='idle')return;if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();leave('map')}if(event.key==='Tab'){const container=state.phase==='arrived'?screen:flight,items=[...container.querySelectorAll('button,a[href]')].filter(el=>el.getClientRects().length);const first=items[0],last=items[items.length-1];if(event.shiftKey&&(document.activeElement===first||!container.contains(document.activeElement))){event.preventDefault();last?.focus()}else if(!event.shiftKey&&(document.activeElement===last||!container.contains(document.activeElement))){event.preventDefault();first?.focus()}}},true);
})();
